import {useMemo,useState} from "react";
import {Button,Card,Divider,PageHeader,StatusPill,Typography} from "@autograph/components";
import {SchemaFormComposition,type SchemaFormValue} from "@autograph/compositions";
type V={title:string;department:string;status:string;salary:number|null;startDate:string;endDate:string}; type E=Partial<Record<keyof V,string>>;
const blank:V={title:"",department:"",status:"draft",salary:null,startDate:"",endDate:""};
const sample:V={title:"Senior People Analyst",department:"people-operations",status:"draft",salary:115000,startDate:"2026-10-01",endDate:"2027-09-30"};
const deps:Record<string,string>={"people-operations":"People Operations",finance:"Finance",engineering:"Engineering",sales:"Sales"}; const statuses:Record<string,string>={draft:"Draft",planned:"Planned"};
function check(v:V){const e:E={};if(!v.title.trim())e.title="Enter a position title.";if(!v.department)e.department="Select a department.";if(!v.status)e.status="Select a status.";if(v.salary===null||!Number.isFinite(v.salary)||v.salary<=0)e.salary="Enter an annual base salary greater than $0.";if(!v.startDate)e.startDate="Enter a start date.";if(!v.endDate)e.endDate="Enter an end date.";if(v.startDate&&v.endDate&&v.endDate<v.startDate)e.endDate="End date must be on or after the start date.";return e}
export default function Screen(){const [v,setV]=useState(sample),[errors,setErrors]=useState<E>({}),[saved,setSaved]=useState<V|null>(null);const spec=useMemo(()=>({type:"schema_form" as const,config:{layout:"grid" as const,submitLabel:"Save draft",resetLabel:"Clear form",fields:[{id:"title",label:"Position title",control:"text" as const,value:v.title,required:true,placeholder:"e.g. Senior People Analyst",error:errors.title},{id:"department",label:"Department",control:"select" as const,value:v.department,required:true,error:errors.department,options:Object.entries(deps).map(([value,label])=>({value,label}))},{id:"status",label:"Status",control:"select" as const,value:v.status,required:true,helper:"Draft keeps the request editable; Planned indicates the intended hiring plan.",error:errors.status,options:Object.entries(statuses).map(([value,label])=>({value,label}))},{id:"salary",label:"Annual base salary (USD)",control:"number" as const,value:v.salary,required:true,helper:"Enter the annual amount in whole US dollars.",error:errors.salary},{id:"startDate",label:"Start date",control:"date" as const,value:v.startDate,required:true,helper:"Expected first day in the position.",error:errors.startDate},{id:"endDate",label:"End date",control:"date" as const,value:v.endDate,required:true,helper:"Use the expected end of the position term.",error:errors.endDate}]} }),[v,errors]);function change(id:string,value:SchemaFormValue){setV(x=>({...x,[id]:value} as V));setErrors(x=>({...x,[id]:undefined}))}function submit(){const e=check(v);setErrors(e);if(!Object.keys(e).length)setSaved({...v})}return <main className="min-h-screen bg-[var(--color-bg-page)] px-[var(--space-6)] py-[var(--space-8)] text-[var(--color-text-primary)]"><div className="mx-auto flex w-full max-w-[960px] flex-col gap-[var(--space-6)]"><PageHeader title="New position request" subtitle="Capture the core hiring details People Operations needs. All fields marked Required must be completed before saving the draft." actions={<StatusPill label={saved?"Draft confirmed":"Draft in progress"} tone={saved?"success":"info"}/>}/>{saved?<Card className="flex flex-col gap-[var(--space-5)] p-[var(--space-6)]"><div><Typography as="h2" variant="section-title" className="m-0">Draft saved in this preview</Typography><Typography tone="secondary" className="mt-[var(--space-1)] mb-0">Review the captured details below. No external system was updated.</Typography></div><Divider/><div className="grid gap-[var(--space-4)] sm:grid-cols-2"><Fact l="Position title" x={saved.title}/><Fact l="Department" x={deps[saved.department]}/><Fact l="Annual base salary" x={new Intl.NumberFormat("en-US",{style:"currency",currency:"USD",maximumFractionDigits:0}).format(saved.salary??0)}/><Fact l="Position term" x={`${date(saved.startDate)} – ${date(saved.endDate)}`}/></div><StatusPill label={statuses[saved.status]} tone="neutral"/><div className="flex gap-[var(--space-2)]"><Button intent="primary" onClick={()=>setSaved(null)}>Edit draft</Button><Button intent="secondary" onClick={()=>{setV(blank);setErrors({});setSaved(null)}}>Start another request</Button></div></Card>:<Card className="flex flex-col gap-[var(--space-5)] p-[var(--space-6)]"><div><Typography as="h2" variant="section-title" className="m-0">Position details</Typography><Typography tone="secondary" className="mt-[var(--space-1)] mb-0">Required: title, department, status, annual base salary, and both dates.</Typography></div><Divider/><SchemaFormComposition spec={spec} onFieldChange={change} onSubmit={submit} onReset={()=>{setV(blank);setErrors({})}}/></Card>}</div></main>}
function Fact({l,x}:{l:string;x:string}){return <div><Typography variant="micro" tone="muted" className="m-0">{l}</Typography><Typography variant="body-strong" className="mt-[var(--space-1)] mb-0">{x}</Typography></div>} function date(x:string){return new Intl.DateTimeFormat("en-US",{month:"short",day:"numeric",year:"numeric",timeZone:"UTC"}).format(new Date(x+"T00:00:00Z"))}
